package accuracy

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"
)

// generatedHeader opens the file GoSource writes. Go's tools read the form
// "Code generated ... DO NOT EDIT." as a file no one edits by hand.
const generatedHeader = "// Code generated by go run ./scripts/accuracy -write, from the lines it writes docs/accuracy.md from. DO NOT EDIT.\n\npackage accuracy\n\n"

// GoSource is the Go file that compiles the record into a release, as Built.
// The same record always gives the same bytes.
func (r Record) GoSource() ([]byte, error) {
	var source bytes.Buffer
	source.WriteString(generatedHeader)
	source.WriteString("// Built is the accuracy page's lines for its last Window days, as the page\n// stood when this release was built.\n")
	if len(r.Lines) == 0 {
		source.WriteString("var Built = Record{}\n")
	} else {
		source.WriteString("var Built = Record{Lines: []Line{\n")
		for _, line := range r.Lines {
			source.WriteString("\t{" + strings.Join(line.fields(), ", ") + "},\n")
		}
		source.WriteString("}}\n")
	}
	formatted, err := format.Source(source.Bytes())
	if err != nil {
		return nil, fmt.Errorf("accuracy: format the record: %w", err)
	}
	return formatted, nil
}

// fields are the line's fields as Go writes them. An empty field is left
// out, so the record reads back as the line it was written from.
func (l Line) fields() []string {
	fields := []string{fmt.Sprintf("Day: %q", l.Day)}
	if len(l.Sources) > 0 {
		quoted := make([]string, len(l.Sources))
		for i, source := range l.Sources {
			quoted[i] = fmt.Sprintf("%q", source)
		}
		fields = append(fields, "Sources: []string{"+strings.Join(quoted, ", ")+"}")
	}
	if len(l.Agents) > 0 {
		agents := make([]string, len(l.Agents))
		for i, agent := range l.Agents {
			agents[i] = fmt.Sprintf("{Name: %q, Version: %q}", agent.Name, agent.Version)
		}
		fields = append(fields, "Agents: []Agent{"+strings.Join(agents, ", ")+"}")
	}
	fields = append(fields, fmt.Sprintf("Verdict: %q", l.Verdict))
	if l.TokenError != "" {
		fields = append(fields, fmt.Sprintf("TokenError: %q", l.TokenError))
	}
	return fields
}
